tools.example:
// Convert the active layer to a Smart Object, then apply an editable Gaussian Blur
app.activeDocument.activeLayer.isBackgroundLayer = false;
executeAction(stringIDToTypeID("newPlacedLayer"), undefined, DialogModes.NO);
// Any filter applied now becomes a Smart Filter
app.activeDocument.activeLayer.applyGaussianBlur(4.5);

// Non-destructive soft glow: blur a duplicate and screen it back
var doc = app.activeDocument;
var copy = doc.activeLayer.duplicate();
doc.activeLayer = copy;
copy.applyGaussianBlur(12.0);
copy.blendMode = BlendMode.SCREEN;
copy.opacity = 60;

// Horizontal speed streak on a duplicated layer
var doc = app.activeDocument;
var streak = doc.activeLayer.duplicate();
doc.activeLayer = streak;
streak.applyMotionBlur(0, 120);   // angle 0 degrees, distance 120 px

// Zoom burst centred on the image centre
var doc = app.activeDocument;
doc.activeLayer.applyRadialBlur(30, RadialBlurMethod.ZOOM, RadialBlurQuality.BEST);

// Flatten skin tone while keeping outlines crisp
app.activeDocument.activeLayer.applySmartBlur(
  8.0,                     // radius
  30.0,                    // threshold
  SmartBlurQuality.HIGH,
  SmartBlurMode.NORMAL
);

// Displace the current layer using a prepared greyscale map
var map = new File("D:/assets/fabric_map.psd");
app.activeDocument.activeLayer.applyDisplace(
  10,                                 // horizontalScale
  10,                                 // verticalScale
  DisplacementMapType.STRETCHTOFIT,
  UndefinedAreas.REPEATEDGEPIXELS,
  map
);

// Turn a panorama into a 'tiny planet'
var doc = app.activeDocument;
// square the canvas and flip vertically first for the classic look
doc.resizeImage(UnitValue(2000, "px"), UnitValue(2000, "px"), null, ResampleMethod.BICUBIC);
doc.activeLayer.applyPolarCoordinates(PolarConversionType.RECTANGULARTOPOLAR);

var layer = app.activeDocument.activeLayer;

// Simple ripple
layer.applyRipple(120, RippleSize.MEDIUM);

// Full wave control: 5 generators, sine wave, edge pixels repeated
layer.applyWave(5, 10, 80, 5, 35, 100, 100,
                WaveType.SINE, UndefinedAreas.REPEATEDGEPIXELS, 0);

// Pond ripples radiating from the selection centre
layer.applyZigZag(35, 8, ZigZagType.PONDRIPPLES);

// Bend the layer with a three-point S-curve
app.activeDocument.activeLayer.applyShear(
  [[0, 0], [30, 128], [0, 255]],       // curve as [x, y] pairs
  UndefinedAreas.REPEATEDGEPIXELS
);

// Map flat artwork onto a sphere
var doc = app.activeDocument;
// make a circular selection first
doc.selection.select([[200,200],[600,200],[600,600],[200,600]]);
doc.activeLayer.applySpherize(100, SpherizeMode.NORMAL);
doc.selection.deselect();

// Add fine monochromatic grain to a 50% grey layer set to Overlay
var doc = app.activeDocument;
var grain = doc.artLayers.add();
doc.activeLayer = grain;
var grey = new SolidColor(); grey.rgb.hexValue = "808080";
doc.selection.selectAll();
doc.selection.fill(grey);
doc.selection.deselect();
grain.applyAddNoise(6.0, NoiseDistribution.GAUSSIAN, true);
grain.blendMode = BlendMode.OVERLAY;

// De-speckle a noisy scan, then use a large radius for frequency separation
var doc = app.activeDocument;
doc.activeLayer.applyMedianNoise(2);       // gentle clean-up

var lowFreq = doc.activeLayer.duplicate();
doc.activeLayer = lowFreq;
lowFreq.applyMedianNoise(12);              // low-frequency base layer

// Unsharp Mask on a duplicated layer, then Smart Sharpen via the UI
var doc = app.activeDocument;
var sharp = doc.activeLayer.duplicate();
doc.activeLayer = sharp;
sharp.applyUnSharpMask(
  120,    // amount  1-500 (%)
  1.2,    // radius  0.1-250.0 (px)
  4       // threshold 0-255
);
// One-click variants:
// sharp.applySharpen();
// sharp.applySharpenMore();
// sharp.applySharpenEdges();

var layer = app.activeDocument.activeLayer;

// High-pass sharpening: run on a duplicate set to Overlay
layer.applyHighPass(2.5);          // radius in px
layer.blendMode = BlendMode.OVERLAY;

// Grow / shrink a mask
// layer.applyMaximum(2);
// layer.applyMinimum(2);

// Build a seamless tile: offset by half the canvas and wrap
var doc = app.activeDocument;
doc.activeLayer.applyOffset(
  UnitValue(doc.width.value / 2, "px"),
  UnitValue(doc.height.value / 2, "px"),
  OffsetUndefinedAreas.WRAPAROUND
);

